44	import type { SendEmailProxy } from '@/types/actions/SendEmail';
45	
46	type FinishedFilter = 'all' | 'finished' | 'active';
47	type AuthFilter = 'all' | 'invited' | 'claimed';
48	
49	const finishedFilterOptions = [
50	    { label: 'All', value: 'all' },
51	    { label: 'Finished', value: 'finished' },
52	    { label: 'Active', value: 'active' },
53	];
54	
55	const authFilterOptions = [
56	    { label: 'All', value: 'all' },
57	    { label: 'Invited', value: 'invited' },
58	    { label: 'Claimed', value: 'claimed' },
59	];
60	
61	export interface Props {
62	    players: PlayerDataType[];
63	    userEmails?: string[];
64	    userIdByEmail?: Record<string, string>;
65	    onAddPlayerInvite: AddPlayerInviteProxy;
66	    onSendEmail: SendEmailProxy;
67	}
68	
69	/**
70	 * Admin table for managing players, invitations, and email verification.
71	 *
72	 * @param props - Component props.
73	 * @param props.players - Players to render in the table.
74	 * @param props.userEmails - Better Auth user emails to determine onboarding status.
75	 * @returns The rendered admin player list table.
76	 */
77	export const AdminPlayerList = ({
78	    players,
79	    userEmails,
80	    userIdByEmail,
81	    onAddPlayerInvite,
82	    onSendEmail,
83	}: Props) => {
84	    const router = useRouter();
85	    const userEmailSet = useMemo(
86	        () => new Set((userEmails ?? [])
87	            .map((email) => normalizeEmail(email)).filter((email) => email.length > 0)),
88	        [userEmails],
89	    );
90	    const [sortKey, setSortKey] = useState<SortKey>('id');
91	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
92	    const [selectedIds, setSelectedIds] = useState<number[]>([]);
93	    const [filter, setFilter] = useState('');
94	    const [filterFinished, setFilterFinished] = useState<FinishedFilter>('all');
95	    const [filterAuth, setFilterAuth] = useState<AuthFilter>('all');
96	
97	    /**
98	     * Filters players by name and the active tri-state filters.
99	     *
100	     * @returns The filtered player list.
101	     */
102	    const filteredPlayers = useMemo(() => {
103	        if (!players) return [];
104	        const trimmedFilter = filter.trim().toLowerCase();
105	        return players.filter((player) => {
106	            if (trimmedFilter && !player.name?.toLowerCase().includes(trimmedFilter)) return false;
107	            if (filterFinished === 'finished' && !player.finished) return false;
108	            if (filterFinished === 'active' && player.finished) return false;
109	            const claimed = isOnboarded(player, userEmailSet);
110	            if (filterAuth === 'claimed' && !claimed) return false;
111	            if (filterAuth === 'invited' && claimed) return false;
112	            return true;
113	        });
114	    }, [players, filter, filterFinished, filterAuth, userEmailSet]);
115	
116	    /**
117	     * Applies sorting to the filtered players.
118	     *
119	     * @returns The sorted player list.
120	     */
121	    const sortedPlayers = useMemo(() => {
122	        const data = [...filteredPlayers];
123	        data.sort((a, b) => comparePlayers(a, b, sortKey, sortDirection, userEmailSet));
124	        return data;
125	    }, [filteredPlayers, sortKey, sortDirection, userEmailSet]);
126	
127	    if (!players) {
128	        return (
129	            <Text>Loading players...</Text>
130	        );
131	    }
132	
133	    if (players.length === 0) {
134	        return (
135	            <Text>No players found.</Text>
136	        );
137	    }
138	
139	    /**
140	     * Selects or clears all visible players.
141	     *
142	     * @param checked - Whether the select-all checkbox is checked.
143	     */
144	    const toggleSelectAll = (checked: boolean) => {
145	        setSelectedIds(checked ? filteredPlayers.map((player) => player.id) : []);
146	    };
147	
148	    /**
149	     * Toggles a single player row selection.
150	     *
151	     * @param playerId - The player ID to toggle.
152	     * @param checked - Whether the checkbox is checked.
153	     */
154	    const toggleSelectPlayer = (playerId: number, checked: boolean) => {
155	        setSelectedIds((prev) => (
156	            checked ?
157	                [...prev, playerId] :
158	                prev.filter((id) => id !== playerId)
159	        ));
160	    };
161	
162	    const allSelected = filteredPlayers.length > 0 && selectedIds.length === filteredPlayers.length;
163	    const someSelected = selectedIds.length > 0 && !allSelected;
164	    const hasSelection = selectedIds.length > 0;
165	    const selectedPlayers = players.filter((player) => selectedIds.includes(player.id));
166	
167	    /**
168	     * Renders a sortable header label with the current sort icon.
169	     *
170	     * @param label - Column display label.
171	     * @param key - Column sort key.
172	     * @returns A sortable header element.
173	     */
174	    const renderSortHeader = (label: string, key: SortKey) => (
175	        <UnstyledButton
176	            type="button"
177	            onClick={() => handleSort(key)}
178	            aria-label={`Sort by ${label}`}
179	        >
180	            <Group gap={6} wrap="nowrap">
181	                <Text span>{label}</Text>
182	                {sortKey === key ? (
183	                    sortDirection === 'asc' ?
184	                        <IconSortAscending size={16} aria-hidden="true" focusable={false} /> :
185	                        <IconSortDescending size={16} aria-hidden="true" focusable={false} />
186	                ) : null}
187	            </Group>
188	        </UnstyledButton>
189	    );
190	
191	    /**
192	     * Updates the sort state for the selected column.
193	     *
194	     * @param key - Column sort key.
195	     */
196	    const handleSort = (key: SortKey) => {
197	        if (key === sortKey) {
198	            setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
199	            return;
200	        }
201	        setSortKey(key);
202	        setSortDirection('asc');
203	    };
204	
205	    /**
206	     * Sends onboarding invites and extra email verifications for the selected
207	     * players. Not expected to called with an empty list since the button is
208	     * disabled, but will handle that case anyway.
209	     *
210	     * @param onboardPlayers - The players to onboard.
211	     * @returns A promise that resolves when onboarding emails are handled.
212	     */
213	    const handleOnboardPlayers = async (onboardPlayers: PlayerDataType[]) => {
214	        const id = notifications.show({
215	            loading: true,
216	            title: 'Onboarding players',
217	            message: 'Sending onboarding emails...',
218	            autoClose: false,
219	            withCloseButton: false,
220	        });
221	
222	        try {
223	            let inviteSent = 0;
224	            let inviteSkipped = 0;
225	            for (const player of onboardPlayers) {
226	                const email = getPreferredEmail(player);
227	                if (!email) {
228	                    inviteSkipped += 1;
229	                } else {
230	                    const inviteLink = await onAddPlayerInvite(player.id, email);
231	                    const html = buildInviteEmail(inviteLink);
232	                    const cc = 'footy@toastboy.co.uk';
233	                    await onSendEmail({
234	                        to: email,
235	                        cc,
236	                        subject: 'Welcome to Toastboy FC!',
237	                        html,
238	                    });
239	                    inviteSent += 1;
240	                }
241	            }
242	
243	            notifications.update({
244	                id,
245	                color: 'teal',
246	                title: 'Onboarding sent',
247	                message: [
248	                    `Invites: ${inviteSent} sent`,
