1	'use client';
2	
3	import type { MantineColor } from '@mantine/core';
4	import {
5	    Button,
6	    Card,
7	    CardSection,
8	    Checkbox,
9	    Container,
10	    Flex,
11	    Group,
12	    Paper,
13	    Select,
14	    Stack,
15	    Text,
16	    TextInput,
17	    Title,
18	} from '@mantine/core';
19	import { useForm } from '@mantine/form';
20	import { notifications } from '@mantine/notifications';
21	import { IconAlertTriangle, IconCheck } from '@tabler/icons-react';
22	import { PlayerResponse } from 'prisma/generated/enums';
23	import { useEffect, useMemo, useRef, useState } from 'react';
24	
25	import { config } from '@/lib/config';
26	import { SubmitResponseProxy } from '@/types/actions/SubmitResponse';
27	import { OutcomePlayerType } from '@/types/OutcomePlayerType';
28	
29	interface ResponsesFormProps {
30	    gameId: number;
31	    gameDate: string;
32	    responses: OutcomePlayerType[];
33	    submitResponse: SubmitResponseProxy;
34	}
35	
36	type ResponseOption = PlayerResponse | 'None';
37	const ResponseOption = {
38	    ...PlayerResponse,
39	    None: 'None' as const,
40	};
41	
42	type ResponseValues = Pick<OutcomePlayerType, 'response' | 'goalie' | 'comment'>;
43	interface ResponsesFormValues {
44	    byPlayerId: Record<number, ResponseValues>;
45	}
46	
47	const toResponseValues = (row: OutcomePlayerType): ResponseValues => ({
48	    response: row.response ?? null,
49	    goalie: !!row.goalie,
50	    // v8 ignore next -- comment is always a string in practice (Prisma default '')
51	    comment: row.comment ?? '',
52	});
53	
54	const responseGroupBarColor: Record<ResponseOption, MantineColor> = {
55	    [ResponseOption.Yes]: 'green.6',
56	    [ResponseOption.No]: 'red.6',
57	    [ResponseOption.Dunno]: 'yellow.6',
58	    [ResponseOption.Excused]: 'gray.6',
59	    [ResponseOption.Flaked]: 'gray.6',
60	    [ResponseOption.Injured]: 'gray.6',
61	    [ResponseOption.None]: 'gray.6',
62	};
63	
64	export const ResponsesForm = ({
65	    gameId,
66	    gameDate,
67	    responses,
68	    submitResponse,
69	}: ResponsesFormProps) => {
70	    const form = useForm<ResponsesFormValues>({
71	        initialValues: {
72	            byPlayerId: Object.fromEntries(responses.map((row) => [row.playerId, toResponseValues(row)])),
73	        },
74	    });
75	    const [savingId, setSavingId] = useState<number | null>(null);
76	    const [filter, setFilter] = useState('');
77	
78	    // Re-sync form values when the responses prop changes (e.g. after
79	    // revalidate / SSE refresh). Preserve any in-progress edits by only
80	    // overwriting rows whose form values still match the previous baseline.
81	    const prevResponsesRef = useRef(responses);
82	    useEffect(() => {
83	        const prevBaselineById = new Map(
84	            prevResponsesRef.current.map((row) => [row.playerId, toResponseValues(row)]),
85	        );
86	        for (const row of responses) {
87	            const newBaseline = toResponseValues(row);
88	            const oldBaseline = prevBaselineById.get(row.playerId) ?? newBaseline;
89	            const current = form.values.byPlayerId[row.playerId];
90	            const userEdited =
91	                !!current && (
92	                    current.response !== oldBaseline.response ||
93	                    current.goalie !== oldBaseline.goalie ||
94	                    current.comment !== oldBaseline.comment
95	                );
96	            if (!userEdited) {
97	                form.setFieldValue(`byPlayerId.${row.playerId}`, newBaseline);
98	            }
99	        }
100	        prevResponsesRef.current = responses;
101	        // eslint-disable-next-line react-hooks/exhaustive-deps -- form identity is stable; we only want to react to responses changes
102	    }, [responses]);
103	
104	    const isRowDirty = (row: OutcomePlayerType) => {
105	        const baseline = toResponseValues(row);
106	        // v8 ignore next -- form is always initialised from the same rows array
107	        const current = form.values.byPlayerId[row.playerId] ?? baseline;
108	
109	        return (
110	            baseline.response !== current.response ||
111	            baseline.goalie !== current.goalie ||
112	            baseline.comment !== current.comment
113	        );
114	    };
115	
116	    const grouped = useMemo(() => {
117	        const filteredRows = responses.filter((row) => {
118	            const searchTerm = filter.toLowerCase();
119	            // v8 ignore next -- optional chaining on name is a type-safety guard
120	            return (row.player.name?.toLowerCase().includes(searchTerm));
121	        });
122	
123	        return {
124	            yes: filteredRows.filter((r) => r.response === ResponseOption.Yes),
125	            no: filteredRows.filter((r) => r.response === ResponseOption.No),
126	            dunno: filteredRows.filter((r) => r.response === ResponseOption.Dunno),
127	            excused: filteredRows.filter((r) => r.response === ResponseOption.Excused),
128	            flaked: filteredRows.filter((r) => r.response === ResponseOption.Flaked),
129	            injured: filteredRows.filter((r) => r.response === ResponseOption.Injured),
130	            none: filteredRows.filter((r) => r.response == null),
131	        };
132	    }, [responses, filter]);
133	
134	    const handleSubmit = async (row: OutcomePlayerType) => {
135	        // v8 ignore next -- form is always initialised from the same rows array
136	        const responseValues = form.values.byPlayerId[row.playerId] ?? toResponseValues(row);
137	        if (!responseValues.response) return;
138	
139	        const notificationId = `response-${row.playerId}`;
140	        notifications.show({
141	            id: notificationId,
142	            loading: true,
143	            title: 'Updating response',
144	            message: 'Updating response...',
145	            autoClose: false,
146	            withCloseButton: false,
147	        });
148	
149	        setSavingId(row.playerId);
150	        try {
151	            await submitResponse({
152	                gameDayId: gameId,
153	                playerId: row.playerId,
154	                response: responseValues.response,
155	                goalie: !!responseValues.goalie,
156	                // v8 ignore next -- form normalises null to '' at init, so comment is always a string
157	                comment: responseValues.comment ?? null,
158	            });
159	            notifications.update({
160	                id: notificationId,
161	                color: 'teal',
162	                title: 'Response updated',
163	                message: 'Response updated successfully',
164	                icon: <IconCheck size={config.notificationIconSize} />,
165	                loading: false,
166	                autoClose: config.notificationAutoClose,
167	            });
168	        } catch (err) {
169	            const errorMessage = err instanceof Error ? err.message : 'Failed to update response';
170	            notifications.update({
171	                id: notificationId,
172	                color: 'red',
173	                title: 'Error',
174	                message: errorMessage,
175	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
176	                loading: false,
177	                autoClose: false,
178	                withCloseButton: true,
179	            });
180	        } finally {
181	            setSavingId(null);
182	        }
183	    };
184	
185	    const renderGroup = (title: ResponseOption, items: OutcomePlayerType[]) => {
186	        if (items.length === 0) return null;
187	
188	        return (
189	            <Card key={title} withBorder shadow="xs" p="md" role="region" aria-label={title}>
190	                <CardSection h={6} bg={responseGroupBarColor[title]} />
