68	export const ResponsesForm = ({
69	    gameId,
70	    gameDate,
71	    responses,
72	    submitResponse,
73	}: ResponsesFormProps) => {
74	    const form = useForm<ResponsesFormValues>({
75	        initialValues: {
76	            byPlayerId: Object.fromEntries(responses.map((row) => [row.playerId, toResponseValues(row)])),
77	        },
78	    });
79	    const [savingId, setSavingId] = useState<number | null>(null);
80	    const [filter, setFilter] = useState('');
81	
82	    // Re-sync form values when the responses prop changes (e.g. after
